//! URL parsing and validation, re-implemented to match the reference C++ binary.

/// A parsed URL.
pub struct URL {
    scheme: String,
    host: String,
    port: String,
    path: String,
}

impl URL {
    /// Parse a URL string. Operates on bytes so non-ASCII input never panics.
    pub fn new(url: &str) -> URL {
        let bytes = url.as_bytes();

        // 1. scheme split on first "://"
        let rest: &[u8] = match find_sub(bytes, b"://") {
            Some(idx) => {
                // idx is at ':', ASCII boundary, safe to slice
                return Self::with_scheme(&url[..idx], &bytes[idx + 3..]);
            }
            None => {
                return Self::with_scheme("", bytes);
            }
        };
        #[allow(unreachable_code)]
        {
            let _ = rest;
            unreachable!()
        }
    }

    fn with_scheme(scheme: &str, rest: &[u8]) -> URL {
        // 2. cut at earliest of first '?' or first '#'
        let mut end = rest.len();
        if let Some(i) = rest.iter().position(|&b| b == b'?') {
            end = end.min(i);
        }
        if let Some(i) = rest.iter().position(|&b| b == b'#') {
            end = end.min(i);
        }
        let rest = &rest[..end];

        // 3. split at first '/'
        let (authority, path): (&[u8], &[u8]) = match rest.iter().position(|&b| b == b'/') {
            Some(i) => (&rest[..i], &rest[i..]),
            None => (rest, &[]),
        };

        // 4. userinfo: split at first '@'
        let hostport: &[u8] = match authority.iter().position(|&b| b == b'@') {
            Some(i) => &authority[i + 1..],
            None => authority,
        };

        // 5. port: split at first ':'
        let (host, port): (&[u8], &[u8]) = match hostport.iter().position(|&b| b == b':') {
            Some(i) => (&hostport[..i], &hostport[i + 1..]),
            None => (hostport, &[]),
        };

        URL {
            scheme: scheme.to_string(),
            host: String::from_utf8_lossy(host).into_owned(),
            port: String::from_utf8_lossy(port).into_owned(),
            path: String::from_utf8_lossy(path).into_owned(),
        }
    }

    pub fn scheme(&self) -> &str {
        &self.scheme
    }

    pub fn host(&self) -> &str {
        &self.host
    }

    pub fn port(&self) -> &str {
        &self.port
    }

    pub fn path(&self) -> &str {
        &self.path
    }
}

/// Find first occurrence of needle in haystack, returning the byte index.
fn find_sub(haystack: &[u8], needle: &[u8]) -> Option<usize> {
    if needle.is_empty() || haystack.len() < needle.len() {
        return None;
    }
    haystack
        .windows(needle.len())
        .position(|w| w == needle)
}

pub fn is_scheme_valid(s: &str) -> bool {
    let b = s.as_bytes();
    if b.is_empty() || !b[0].is_ascii_alphabetic() {
        return false;
    }
    b[1..]
        .iter()
        .all(|&c| c.is_ascii_alphanumeric() || c == b'+' || c == b'-' || c == b'.')
}

pub fn is_host_valid(h: &str) -> bool {
    let b = h.as_bytes();
    !b.is_empty()
        && b.iter()
            .all(|&c| c.is_ascii_alphanumeric() || c == b'.' || c == b'-' || c == b'[' || c == b']')
}

pub fn is_port_valid(p: &str) -> bool {
    let b = p.as_bytes();
    let mut i = 0;
    // skip C-locale whitespace
    while i < b.len() && matches!(b[i], b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r') {
        i += 1;
    }
    // optional sign
    let mut negative = false;
    if i < b.len() && (b[i] == b'+' || b[i] == b'-') {
        negative = b[i] == b'-';
        i += 1;
    }
    // require at least one digit
    if i >= b.len() || !b[i].is_ascii_digit() {
        return false;
    }
    // parse digit prefix with i32 overflow detection (std::stoi throws out_of_range)
    let mut value: i64 = 0;
    while i < b.len() && b[i].is_ascii_digit() {
        value = value * 10 + (b[i] - b'0') as i64;
        if value > i32::MAX as i64 {
            return false;
        }
        i += 1;
    }
    let value = if negative { -value } else { value };
    (0..=65535).contains(&value)
}

pub fn is_valid_url(u: &str) -> bool {
    let url = URL::new(u);
    !url.host().is_empty() || !url.path().is_empty()
}

pub fn split_path(p: &str) -> Vec<&str> {
    p.split('/').filter(|s| !s.is_empty()).collect()
}

