mod url_parser;

use url_parser::{is_host_valid, is_port_valid, is_scheme_valid, is_valid_url, split_path, URL};

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 2 {
        std::process::exit(1);
    }
    let url = &args[1];
    let parser = URL::new(url);

    println!("{}", is_valid_url(url) as i32);
    println!("{}", is_scheme_valid(parser.scheme()) as i32);
    println!("{}", is_host_valid(parser.host()) as i32);
    println!("{}", is_port_valid(parser.port()) as i32);

    let segments = split_path(parser.path());
    println!("{}", segments.len());
    for seg in segments {
        println!("{}", seg);
    }
}

