pub fn new(url: &str) -> URL {
    // 1. cut the whole url at the earliest of the first '?' or first '#'
    let bytes = cut_query_fragment(url.as_bytes());
    // url is valid UTF-8 and the cut index is at an ASCII byte (or len)
    let cut = &url[..bytes.len()];

    // 2. scheme split on first "://"; without it there is no authority,
    //    and the whole rest is the path.
    match find_sub(bytes, b"://") {
        // idx is at ':', an ASCII boundary, so slicing is safe
        Some(idx) => Self::from_authority(&cut[..idx], &bytes[idx + 3..]),
        None => URL {
            scheme: String::new(),
            host: String::new(),
            port: String::new(),
            path: String::from_utf8_lossy(bytes).into_owned(),
        },
    }
}

