use strict; use warnings;
my $REF  = '/workspace/dataset/test16_executable';
my $RUST = '/output/test16';
my @ALPHA = (':','/','@','?','#','[',']','.','-','a','1',' ');

sub run {
    my ($bin, $s) = @_;
    my $pid = open(my $fh, '-|');
    die "fork failed" unless defined $pid;
    if ($pid == 0) {
        open(STDERR, '>', '/dev/null');
        exec($bin, $s) or exit(127);
    }
    local $/; my $out = <$fh>; $out = '' unless defined $out;
    close($fh);
    my $rc = $? >> 8;
    return ($rc, $out);
}

sub qrepr {
    my ($s) = @_;
    $s =~ s/\\/\\\\/g; $s =~ s/'/\\'/g; $s =~ s/\n/\\n/g; $s =~ s/\r/\\r/g; $s =~ s/\t/\\t/g;
    return "'$s'";
}

my %seen;
my $count = 0;
my @mism;

sub test {
    my ($s) = @_;
    return if $seen{$s}++;
    $count++;
    my ($rc1,$o1) = run($REF,$s);
    my ($rc2,$o2) = run($RUST,$s);
    if ($rc1 != $rc2 || $o1 ne $o2) {
        push @mism, [$s,$rc1,$o1,$rc2,$o2];
    }
}

# exhaustive lengths 0-3
for my $L (0..3) {
    my @idx = (0) x $L;
    while (1) {
        test(join('', map { $ALPHA[$_] } @idx));
        my $i = $L - 1;
        while ($i >= 0) {
            if (++$idx[$i] < @ALPHA) { last; }
            $idx[$i] = 0; $i--;
        }
        last if $i < 0;
    }
}

# random sample lengths 4-6, 20000 samples
srand(12345);
my $n = 0;
while ($n < 20000) {
    my $L = 4 + int(rand(3));
    my $s = join('', map { $ALPHA[int(rand(@ALPHA))] } 1..$L);
    next if $seen{$s};
    test($s); $n++;
}

# structured: multiple '://' and '?'/'#' before '://'
my @frags = ('://','?','#',':','/','@','a','1','.','[',']');
for (1..6000) {
    my $k = 2 + int(rand(5));
    my $s = join('', map { $frags[int(rand(@frags))] } 1..$k);
    test($s);
}
for my $s ('?://','#://','a://b://c','://://://','?#://','a?b://c#d://e',
           '://?://#://','a://?://',':://:://','://a://1://.://') {
    test($s);
}

print "total tested: $count\n";
print "mismatches: " . scalar(@mism) . "\n";
my $shown = 0;
for my $m (@mism) {
    last if $shown++ >= 50;
    my ($s,$rc1,$o1,$rc2,$o2) = @$m;
    print "input=" . qrepr($s) . "\n";
    print "  ref : rc=$rc1 out=" . qrepr($o1) . "\n";
    print "  rust: rc=$rc2 out=" . qrepr($o2) . "\n";
}
PERLEOF
