use strict; use warnings;
use Encode qw(encode);

my $REF  = '/workspace/dataset/test16_executable';
my $RUST = '/output/test16';

my @ports;
for (my $i = -2; $i <= 70000; $i += 37) { push @ports, "$i"; }
push @ports, qw(-2 -1 0 1 69999 70000 65535 65536);
for my $k (0..19) { my $p = 10**$k; push @ports, "$p", "-$p"; }
push @ports, qw(2147483647 2147483648 4294967295 4294967296
                9223372036854775807 9223372036854775808 99999999999999999999
                -2147483648 -2147483649 -9223372036854775808);
push @ports, ' 80', '80 ', "  65535\t", "\t42", ' ', '  ', "80\n", "\n80", '8 0', ' 8 0 ';
push @ports, qw(+80 -0 ++80 --80 +-80 -+80 + - +0 -1 ++ --);
push @ports, qw(80abc 80:90 0x50 08o 65535.9 1e5 80/ 80? 80# 080 00080 000
                abc abc80 0b101 0o120 1_000 80,000 5.0 .5 e5 0x x80);
push @ports, '', 'a', ':', '/', '?', '#', '@', '.', ',', 'abc def', '!@#$%';
# unicode digits (as code points, encoded later)
push @ports, "\x{0668}\x{0660}", "\x{FF18}\x{FF10}", "\x{0661}\x{0662}\x{0663}",
             "\x{FF11}\x{FF12}\x{FF13}", "\x{096E}\x{0966}", "\x{0E58}\x{0E50}",
             "\x{1D7D8}\x{1D7D8}";
for my $n (100,150,200,250,300) {
    push @ports, '9' x $n, '0' x $n, '1' . ('0' x ($n-1));
}

my %seen;
my @inputs;
for my $p (@ports) {
    next if $seen{$p}++;
    push @inputs, encode('UTF-8', 'http://h:' . $p);
}

sub run {
    my ($bin, $arg) = @_;
    my $pid = open(my $fh, '-|');
    die "fork failed" unless defined $pid;
    if ($pid == 0) {
        open(STDERR, '>', '/dev/null');
        exec($bin, $arg) or exit(127);
    }
    local $/;
    my $out = <$fh>;
    close($fh);
    my $rc = $? >> 8;
    $out = '' unless defined $out;
    return ($out, $rc);
}

my $tested = 0;
my @mismatch;
for my $s (@inputs) {
    my ($o1, $r1) = run($REF, $s);
    my ($o2, $r2) = run($RUST, $s);
    $tested++;
    if ($o1 ne $o2 || $r1 != $r2) {
        push @mismatch, [$s, $o1, $r1, $o2, $r2];
    }
}

sub brepr {
    my ($s) = @_;
    my $r = '';
    for my $c (split //, $s) {
        my $o = ord($c);
        if ($c =~ /[\x20-\x7E]/ && $c ne '\\' && $c ne "'") { $r .= $c; }
        else { $r .= sprintf('\\x%02x', $o); }
    }
    return "'$r'";
}

print "tested $tested inputs, " . scalar(@mismatch) . " mismatches\n";
my $shown = 0;
for my $m (@mismatch) {
    last if $shown++ >= 60;
    print "INPUT ", brepr($m->[0]), "\n";
    print "  ref : rc=$m->[2] stdout=", brepr($m->[1]), "\n";
    print "  rust: rc=$m->[4] stdout=", brepr($m->[3]), "\n";
}
EOF

